class DpvTermStatus(str, Enum):
    """
    How DPV's editors mark a term's standing.
    """
    Accepted = "accepted"
    """
    The Community Group has accepted the term.
    """
    Modified = "modified"
    """
    The term changed in a recent release.
    """
    Sunset = "sunset"
    """
    The term is on its way out of the vocabulary.
    """


class DpvFamily(str, Enum):
    """
    The parts of a release, one file each.
    """
    Core = "core"
    """
    The vocabulary at https://w3id.org/dpv and the terms it adopts from others.
    """
    Personal_Data = "pd"
    """
    The personal data vocabulary.
    """
    Technology = "tech"
    """
    The technology vocabulary.
    """
    Artificial_Intelligence = "ai"
    """
    The artificial intelligence vocabulary.
    """
    Risk = "risk"
    """
    The risk vocabulary.
    """
    Justifications = "justifications"
    """
    The justifications vocabulary.
    """
    Locations = "loc"
    """
    The locations vocabulary.
    """
    Laws_and_Authorities = "legal"
    """
    The legal vocabularies, of each jurisdiction and each EU law.
    """
    Sectors = "sector"
    """
    The sector vocabularies.
    """
    Standards = "standards"
    """
    The vocabularies of other standards.
    """
    Agents = "agents"
    """
    The contributors.
    """
    Examples = "examples"
    """
    The examples.
    """



class DpvVocabulary(ConfiguredBaseModel):
    """
    One of DPV's vocabularies, as its own Turtle file's header describes it.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'class_uri': 'owl:Ontology',
         'from_schema': 'https://w3id.org/lmodel/dpv/dpv_core',
         'title': 'Vocabulary'})

    id: str = Field(default=..., title="ID", description="""The element's IRI as a CURIE or whole, or a blank node's label in an example.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary',
                       'DpvConceptScheme',
                       'DpvAgent',
                       'DpvTerm',
                       'DpvExample']} })
    title: Optional[str] = Field(default=None, title="Title", description="""The element's name.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary', 'DpvResource', 'DpvExample'],
         'slot_uri': 'dcterms:title'} })
    description: Optional[str] = Field(default=None, title="Description", description="""What the element says about itself, as DPV writes it.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary', 'DpvResource', 'DpvExample'],
         'slot_uri': 'dcterms:description'} })
    identifier: Optional[str] = Field(default=None, title="Identifier", description="""The identifier DPV gives the element.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary', 'DpvResource'],
         'slot_uri': 'dcterms:identifier'} })
    bibliographicCitation: Optional[str] = Field(default=None, title="Bibliographic Citation", description="""How DPV asks to be cited.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'dcterms:bibliographicCitation'} })
    conformsTo: Optional[list[str]] = Field(default=None, title="Conforms To", description="""What the element conforms to, as DPV writes it.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary', 'DpvResource'],
         'slot_uri': 'dcterms:conformsTo'} })
    created: Optional[list[str]] = Field(default=None, title="Created", description="""The dates DPV gives for the element's creation.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary', 'DpvTerm', 'DpvExample'],
         'slot_uri': 'dcterms:created'} })
    issued: Optional[str] = Field(default=None, title="Issued", description="""The date of the element's publication.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'dcterms:issued'} })
    modified: Optional[str] = Field(default=None, title="Modified", description="""The date of the element's last change.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary', 'DpvTerm', 'DpvExample'],
         'slot_uri': 'dcterms:modified'} })
    creator: Optional[list[str]] = Field(default=None, title="Creator", description="""The people DPV names as the element's editors.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'dcterms:creator'} })
    contributor: Optional[list[str]] = Field(default=None, title="Contributor", description="""The people DPV names as contributors to the element.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary', 'DpvTerm', 'DpvExample'],
         'slot_uri': 'dcterms:contributor'} })
    publisher: Optional[str] = Field(default=None, title="Publisher", description="""The element's publisher.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'dcterms:publisher'} })
    license: Optional[str] = Field(default=None, title="License", description="""The address of the element's licence.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'dcterms:license'} })
    source: Optional[list[str]] = Field(default=None, title="Source", description="""Where the element comes from, as text or as an address.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary', 'DpvTerm', 'DpvExample'],
         'slot_uri': 'dcterms:source'} })
    doi: Optional[str] = Field(default=None, title="DOI", description="""The vocabulary's digital object identifier.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'bibo:doi'} })
    bibo_status: Optional[str] = Field(default=None, title="Status", description="""The vocabulary's publication status.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'bibo:status'} })
    preferredNamespacePrefix: Optional[str] = Field(default=None, title="Preferred Namespace Prefix", description="""The prefix DPV uses for the vocabulary's namespace.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'vann:preferredNamespacePrefix'} })
    preferredNamespaceUri: Optional[str] = Field(default=None, title="Preferred Namespace URI", description="""The vocabulary's namespace.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'vann:preferredNamespaceUri'} })
    rdfs_Label: Optional[str] = Field(default=None, title="RDFS Label", description="""A short label, under rdfs:Label as DPV writes it, which is not the term rdfs:label.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'rdfs:Label'} })
    versionIRI: Optional[str] = Field(default=None, title="Version IRI", description="""The IRI of this edition of the vocabulary.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'owl:versionIRI'} })
    versionInfo: str = Field(default=..., title="Version", description="""The edition of the vocabulary.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'owl:versionInfo'} })
    schema_version: Optional[str] = Field(default=None, title="Schema.org Version", description="""The edition of the vocabulary, under schema.org's term.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'sdo:version'} })
    isProfileOf: Optional[list[str]] = Field(default=None, title="Is Profile Of", description="""The specifications the vocabulary profiles.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'prof:isProfileOf'} })
    logo: Optional[str] = Field(default=None, title="Logo", description="""The address of the vocabulary's logo.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DpvVocabulary'], 'slot_uri': 'foaf:logo'} })

    @field_validator('id')
    def pattern_id(cls, v):
        pattern=re.compile(r"^[A-Za-z_][A-Za-z0-9_+.-]*:\S*$")
        if isinstance(v, list):
            for element in v:
                if isinstance(element, str) and not pattern.search(element):
                    err_msg = f"Invalid id format: {element}"
                    raise ValueError(err_msg)
        elif isinstance(v, str) and not pattern.search(v):
            err_msg = f"Invalid id format: {v}"
            raise ValueError(err_msg)
        return v

